def investigate(context, acquire):
    hist = acquire("history")
    # Family: put in {ignore, replace, upsert}; trigger in {none, after_insert_log};
    # channel in {changes, total_changes, total_changes_both}.
    # We simulate all 18 members and keep those consistent with every receipt.

    def simulate(put_mode, trig, chan, actions):
        # state: dict key -> value (committed), plus per-connection pending
        committed = {}
        # transaction state per connection: None or dict of pending changes
        tx = {"main": None, "other": None}
        # total_changes counters per connection
        tc = {"main": 0, "other": 0}
        # last changes() on main
        last_changes = 0
        # log rows count (trigger)
        log_rows = 0

        def apply_write(conn, key, value, is_put):
            nonlocal last_changes, log_rows
            # determine current visible value for this connection
            if tx[conn] is not None:
                view = dict(committed)
                view.update(tx[conn])
            else:
                view = committed
            existed = key in view
            old = view.get(key)
            changed = False
            inserted = False
            if is_put:
                if put_mode == "ignore":
                    if not existed:
                        changed = True
                        inserted = True
                elif put_mode == "replace":
                    changed = True
                    if not existed:
                        inserted = True
                else:  # upsert
                    if not existed:
                        changed = True
                        inserted = True
                    elif old != value:
                        changed = True
            else:  # update
                if existed and old != value:
                    changed = True
            if not changed:
                last_changes = 0
                return
            # apply
            if tx[conn] is not None:
                tx[conn][key] = value
            else:
                committed[key] = value
            last_changes = 1
            tc[conn] += 1
            if trig and inserted:
                log_rows += 1

        def apply_delete(conn, key):
            nonlocal last_changes
            if tx[conn] is not None:
                view = dict(committed)
                view.update(tx[conn])
            else:
                view = committed
            if key in view:
                if tx[conn] is not None:
                    tx[conn][key] = None  # mark deleted
                else:
                    del committed[key]
                last_changes = 1
                tc[conn] += 1
            else:
                last_changes = 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                apply_write(conn, act["key"], act["value"], True)
            elif op == "update":
                apply_write(conn, act["key"], act["value"], False)
            elif op == "delete":
                apply_delete(conn, act["key"])
            elif op == "begin":
                tx[conn] = {}
            elif op == "commit":
                if tx[conn] is not None:
                    for k, v in tx[conn].items():
                        if v is None:
                            committed.pop(k, None)
                        else:
                            committed[k] = v
                    tx[conn] = None
            elif op == "rollback":
                tx[conn] = None

        if chan == "changes":
            ch = last_changes
        elif chan == "total_changes":
            ch = tc["main"]
        else:
            ch = tc["main"] + tc["other"]
        return ch, committed

    def committed_view(actions):
        # committed state after sequence, ignoring channel
        committed = {}
        tx = {"main": None, "other": None}
        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op in ("put", "update"):
                key = act["key"]
                val = act["value"]
                if tx[conn] is not None:
                    view = dict(committed)
                    view.update(tx[conn])
                else:
                    view = committed
                existed = key in view
                old = view.get(key)
                if op == "put":
                    # for committed state, put always sets value (ignore/replace/upsert all end with value if inserted or replaced)
                    # ignore: only if not existed; replace/upsert: always set
                    # but we don't know mode here; committed_view is only used for consistency check
                    pass
                # We'll handle in simulate instead
            # placeholder
        return committed

    # Build candidate list
    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for trig in (False, True):
            for chan in ("changes", "total_changes", "total_changes_both"):
                candidates.append((put_mode, trig, chan))

    # Filter by history
    for rec in hist:
        actions = rec["actions"]
        obs = rec["observed"]
        new_cands = []
        for (pm, tg, ch) in candidates:
            sim_ch, sim_committed = simulate(pm, tg, ch, actions)
            # committed_count and sum
            cnt = len(sim_committed)
            sm = sum(sim_committed.values())
            if sim_ch == obs["channel"] and cnt == obs["committed_count"] and sm == obs["committed_sum"]:
                new_cands.append((pm, tg, ch))
        candidates = new_cands

    goal = context.get("goal")
    actions = context.get("actions", [])

    if not candidates:
        return {"value": None, "unresolved": True}

    results = set()
    for (pm, tg, ch) in candidates:
        sim_ch, sim_committed = simulate(pm, tg, ch, actions)
        if goal == "channel":
            results.add(sim_ch)
        elif goal == "committed_count":
            results.add(len(sim_committed))
        elif goal == "committed_sum":
            results.add(sum(sim_committed.values()))
        else:
            return {"value": None, "unresolved": True}

    if len(results) == 1:
        return {"value": list(results)[0], "unresolved": False}
    return {"value": None, "unresolved": True}
